// ---- glassswell --------------------------------------------------------------------------------
const track3 = (() => {
  const RHYTHM = null
  // is the section playing at x, and how hard (0 = no)
  const strokeAt = x => {
    const c = chordAt(x), e = energy(x)
    if (!c || e < 1 || x >= END - 0.5) return 0
    if (!RHYTHM) return 1
    const pat = RHYTHM[e] ?? RHYTHM[2], i = floor(4 * mod(x, 4) + 1e-6), ch = pat ? pat[i] : '-'
    return (ch === 'x' ? 1 : ch === 'o' ? 0.6 : 0) * (mod(4 * x, 1) < 0.8 ? 1 : 0)
  }
  return {
  color: '#bde0fe',
  graph: x => (strokeAt(x) ? chordAt(x)[3].map(n => -1 + (n - 48) / 20) : null),
  midi: x => (strokeAt(x) ? chordAt(x)[3] : []),
  formula: ["Pd = \\Rev\\sum_{j}\\sum_{i=1}^{N} a_i\\,W_{d}\\big(f_j\\,2^{(\\delta_i + v_i(t))/1200}\\big),\\quad W_d = \\sum_k \\frac{B(kf)}{k^{p(d)}}\\sin(2\\pi kft + \\varphi_k)\\ \\text{— N исполнителей на каждой ноте, каждый на несколько центов в стороне, со своим вибрато и местом в зале}"],
  audio() {
    const S = [section('glass', { players: 4, centre: 0, spread: 0.8, vib: 1, attack: 0.6, release: 1.2, seed: 40 }), section('sine', { players: 2, centre: 0, spread: 0.8, vib: 1, attack: 0.8, release: 1.2, seed: 41 })], NONE = [], verb = hall({ size: 1.5, decay: 9, damp: 3000, pre: 0.04, mod: 1.6, wet: 0.5 })
    let F = S.map(() => NONE), last = null
    return x => {
      const st = strokeAt(x), on = st > 0, c = on ? chordAt(x) : null
      if (c && c !== last) { last = c; F = [c[3].map(n => hz(n + 0 - 60, C4)), c[3].map(n => hz(n + 12 - 60, C4))] }
      const lv = ([0.3,0.45,0.62,0.85][Math.max(0, energy(x))] ?? 0.4) * (0.6 + 0.4 * st)
      let l = 0, r = 0
      { const [a, b] = S[0](on ? F[0] : NONE, lv); l += 1 * a; r += 1 * b }
      { const [a, b] = S[1](on ? F[1] : NONE, lv); l += 0.3 * a; r += 0.3 * b }
      const k = 0.65 * (0.7 + 0.5 * lv)
      return verb(k * l, k * r)
    }
  },
}})()

